/// Settings represented by `remote-config-gen.yml`.
public struct GeneratorConfig: Equatable, Sendable {
    /// Path to the Remote Config template export JSON, relative to the config directory.
    public var input: String
    /// Path of the generated Swift file, relative to the config directory.
    public var output: String
    /// Additional namespaces generated by extracting keys from the default namespace.
    public var additionalNamespaces: [String: NamespaceConfig]

    public init(
        input: String,
        output: String,
        additionalNamespaces: [String: NamespaceConfig] = [:],
    ) {
        self.input = input
        self.output = output
        self.additionalNamespaces = additionalNamespaces
    }
}

public extension GeneratorConfig {
    /// Additional namespace that extracts keys from the default namespace.
    struct NamespaceConfig: Equatable, Sendable {
        /// Prefix of the keys to extract. `nil` includes every parameter.
        public var keyPrefix: String?
        /// Keys absent from the Remote Config template that are still included in the namespace.
        public var additionalKeys: [String]

        public init(keyPrefix: String? = nil, additionalKeys: [String] = []) {
            self.keyPrefix = keyPrefix
            self.additionalKeys = additionalKeys
        }
    }
}
